public class FlowToolbarPanelTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    static java.awt.Component find(java.awt.Container root, String name) {
        if (name.equals(root.getName())) {
            return root;
        }
        for (java.awt.Component child : root.getComponents()) {
            if (name.equals(child.getName())) {
                return child;
            }
            if (child instanceof java.awt.Container) {
                java.awt.Component result = find((java.awt.Container) child, name);
                if (result != null) {
                    return result;
                }
            }
        }
        return null;
    }

    static String nameAt(java.awt.Container root, int index) {
        if (index >= root.getComponentCount()) {
            return "(nothing at index " + index + ")";
        }
        return String.valueOf(root.getComponent(index).getName());
    }

    public static void main(String[] args) {
        try {
            FlowToolbarPanel panel = new FlowToolbarPanel();
            java.awt.LayoutManager layout = panel.getLayout();
            check("layout is a FlowLayout", true, layout instanceof java.awt.FlowLayout);
            if (layout instanceof java.awt.FlowLayout) {
                java.awt.FlowLayout flow = (java.awt.FlowLayout) layout;
                check("left aligned", java.awt.FlowLayout.LEFT, flow.getAlignment());
                check("horizontal gap", 8, flow.getHgap());
                check("vertical gap", 4, flow.getVgap());
            } else {
                failures += 3;
                System.out.println("FAIL  cannot inspect alignment or gaps without a FlowLayout");
            }
            check("three buttons added", 3, panel.getComponentCount());
            check("first button", "cut", nameAt(panel, 0));
            check("second button", "copy", nameAt(panel, 1));
            check("third button", "paste", nameAt(panel, 2));
            check("paste button is reachable by name", true,
                    find(panel, "paste") instanceof javax.swing.JButton);
        } catch (Exception e) {
            failures++;
            System.out.println("FAIL  unexpected exception: " + e);
        }
        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

