import java.awt.FlowLayout;
import javax.swing.JButton;
import javax.swing.JPanel;

public class FlowToolbarPanel extends JPanel {

    private final JButton cut = new JButton("Cut");
    private final JButton copy = new JButton("Copy");
    private final JButton paste = new JButton("Paste");

    public FlowToolbarPanel() {
        cut.setName("cut");
        copy.setName("copy");
        paste.setName("paste");
        buildToolbar();
    }

    private void buildToolbar() {
        setLayout(new FlowLayout(FlowLayout.LEFT, 8, 4));
        add(cut);
        add(copy);
        add(paste);
    }
}
